class APIKeyBase(SecurityBase):
    @staticmethod
    def check_api_key(
        api_key: Optional[str],
        auto_error: bool,
        not_authenticated_status_code: int = HTTP_401_UNAUTHORIZED,
        www_authenticate_header: Optional[str] = None,
    ) -> Optional[str]:
        if not api_key:
            if auto_error:
                headers = {}
                if www_authenticate_header:
                    headers["WWW-Authenticate"] = www_authenticate_header
                raise HTTPException(
                    status_code=not_authenticated_status_code, detail="Not authenticated", headers=headers
                )
            return None
        return api_key

